"""Documents generated by Elon in the chat ("Dokumenty od Elona"): letters to HR, grievances, SSP demands...

Flow: when the user asks for a letter, Elon's answer contains one block (see elon_prompt.txt):

    [[DOKUMENT]]
    typ: hr_letter
    tytul: Pismo do HR – niewypłacone nadgodziny
    adresat: HR Department, Jigsaw Food
    temat: Unpaid overtime – request for payment
    jezyk: en
    ---
    Dear HR team, ... Yours sincerely, Anna Kowalska
    ---tlumaczenie---
    (optional translation into the user's language)
    [[/DOKUMENT]]

After the answer has streamed, the server cuts the block out of the message, renders a PDF (PyMuPDF, bundled
DejaVu fonts, user's profile data, an 'ask Elon' brand stamp – not an official seal – and a "not legal advice"
footer), stores PDF + first-page thumbnail (storage.py) and saves the document automatically in the
`chat_documents` collection (separate from uploaded `documents`). Every query is scoped to the owner.

Model output is untrusted: it is only ever used as plain text (HTML-escaped for the PDF), size-capped, and
control characters are removed. Files are served only to the owner (Bearer session) or via a short-lived
HMAC-signed link that the API hands to the owner (for <img> thumbnails and plain download links).
"""
from __future__ import annotations

import hashlib
import hmac
import html
import io
import logging
import re
import time
import unicodedata
import uuid
from datetime import datetime
from pathlib import Path
from typing import Awaitable, Callable, List, Optional, Tuple
from urllib.parse import quote

from fastapi import APIRouter, HTTPException, Request, Response
from pydantic import BaseModel
from starlette.concurrency import run_in_threadpool

import storage
import storage_quota

logger = logging.getLogger("chat_documents")
ASSETS = Path(__file__).parent / "assets"

OPEN_RE = re.compile(r"\[\[\s*DOKUMENT\s*\]\]", re.I)
CLOSE_RE = re.compile(r"\[\[\s*/\s*DOKUMENT\s*\]\]", re.I)
SEP_RE = re.compile(r"^\s*-{3,}\s*$", re.M)
TRANS_RE = re.compile(r"^\s*-{3,}\s*t[lł]umaczenie\s*-{3,}\s*$", re.I | re.M)
_CTRL = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f\u200b-\u200f\u202a-\u202e\u2066-\u2069]")

TYPES = ("hr_letter", "grievance", "ssp_demand", "wage_claim", "holiday_pay", "other")
LANGS = ("en", "pl", "ro")
TITLE_MAX, LINE_MAX, BODY_MAX, BODY_MIN = 120, 200, 8000, 40
MAX_PER_DAY = 30
MAX_STORED = 300
LINK_TTL = 3600  # seconds a signed thumbnail/PDF link stays valid
PUBLIC_EXCLUDE = {"_id", "user_id", "pdf_path", "thumb_path", "deleted", "deleted_at", "created_ts"}


def clean(s: Optional[str], limit: int, multiline: bool = True) -> str:
    s = _CTRL.sub("", (s or "").replace("\r\n", "\n").replace("\r", "\n"))
    s = OPEN_RE.sub("", CLOSE_RE.sub("", s))
    if not multiline:
        s = " ".join(s.split())
    else:
        s = re.sub(r"[ \t]+\n", "\n", s)
        s = re.sub(r"\n{3,}", "\n\n", s)
    return s.strip()[:limit]


def _key(k: str) -> str:
    k = unicodedata.normalize("NFKD", k.strip().lower())
    return "".join(c for c in k if not unicodedata.combining(c)).replace("ł", "l")


KEYS = {"typ": "type", "type": "type", "tytul": "title", "title": "title", "adresat": "recipient",
        "recipient": "recipient", "do": "recipient", "temat": "subject", "subject": "subject",
        "jezyk": "language", "language": "language", "lang": "language"}


def split_document(text: str) -> Tuple[str, Optional[dict]]:
    """Returns (message text without the block, parsed document or None). Never raises."""
    m = OPEN_RE.search(text or "")
    if not m:
        return text, None
    end = CLOSE_RE.search(text, m.end())
    raw = text[m.end(): end.start() if end else len(text)]
    rest = (text[: m.start()] + ("\n\n" + text[end.end():] if end else "")).strip()
    rest = re.sub(r"\n{3,}", "\n\n", rest)
    try:
        spec = parse_block(raw)
    except Exception:
        logger.exception("document block parse failed")
        spec = None
    return rest, spec


def parse_block(raw: str) -> Optional[dict]:
    raw = raw.replace("\r\n", "\n").strip("\n")
    sep = SEP_RE.search(raw)
    if sep and not TRANS_RE.match(raw[sep.start(): sep.end()]):
        head, body = raw[: sep.start()], raw[sep.end():]
    else:  # no header separator: header = leading "key: value" lines
        lines, i = raw.split("\n"), 0
        while i < len(lines) and re.match(r"^\s*[\wąćęłńóśźżăâîșț]+\s*:", lines[i], re.I) and _key(lines[i].split(":", 1)[0]) in KEYS:
            i += 1
        head, body = "\n".join(lines[:i]), "\n".join(lines[i:])
    meta = {}
    for line in head.split("\n"):
        if ":" in line:
            k, v = line.split(":", 1)
            if _key(k) in KEYS:
                meta[KEYS[_key(k)]] = v.strip()
    translation = ""
    t = TRANS_RE.search(body)
    if t:
        body, translation = body[: t.start()], body[t.end():]
    body = clean(body, BODY_MAX)
    if len(body) < BODY_MIN:
        return None
    typ = _key(meta.get("type", "")).replace(" ", "_").replace("-", "_")
    lang = _key(meta.get("language", ""))[:2]
    return {
        "type": typ if typ in TYPES else "other",
        "title": clean(meta.get("title"), TITLE_MAX, False),
        "recipient": clean(meta.get("recipient"), LINE_MAX, False),
        "subject": clean(meta.get("subject"), LINE_MAX, False),
        "language": lang if lang in LANGS else "en",
        "body": body,
        "translation": clean(translation, BODY_MAX),
    }


