def date_text(d: datetime, lang: str) -> str:
    return f"{d.day} {MONTHS.get(lang, MONTHS['en'])[d.month - 1]} {d.year}"


def build_snapshot(user: dict, spec: dict, created: datetime) -> dict:
    """Header data printed on the letter, frozen at creation so PDF and in-app preview always match."""
    lang = spec["language"]
    v = lambda k: clean(str(user.get(k) or ""), LINE_MAX, False)  # noqa: E731
    sender = [x for x in [v("name"), *[p.strip() for p in v("address").split(",") if p.strip()], v("email"), v("phone")] if x]
    employer = v("employer")
    recipient = spec.get("recipient") or (f"{LABELS[lang]['hr']}, {employer}" if employer else LABELS[lang]["hr"])
    rec_lines = [recipient]
    if employer and employer.lower() not in recipient.lower():
        rec_lines.append(employer)
    rec_lines += [p.strip() for p in v("workplace_address").split(",") if p.strip()]
    if v("hr_email"):
        rec_lines.append(v("hr_email"))
    return {"sender_lines": sender[:8], "recipient_lines": rec_lines[:8], "date_text": date_text(created, lang),
            "hr_email": v("hr_email")}


def _p(text: str) -> str:
    paras = [x for x in re.split(r"\n\s*\n", text) if x.strip()]
    return "".join(f"<p>{html.escape(x.strip()).replace(chr(10), '<br/>')}</p>" for x in paras)


CSS = """
@font-face { font-family: dv; src: url(DejaVuSans.ttf); }
@font-face { font-family: dv; src: url(DejaVuSans-Bold.ttf); font-weight: bold; }
* { font-family: dv; font-size: 10.5pt; line-height: 1.45; color: #1d2530; }
p { margin: 0 0 9pt 0; }
.sender { font-size: 9.5pt; color: #3c4654; margin-bottom: 16pt; margin-right: 110pt; }
.sender b { font-size: 11pt; color: #0A2A5C; }
.date { margin-bottom: 14pt; color: #3c4654; }
.to { margin-bottom: 16pt; }
.subject { font-weight: bold; color: #0A2A5C; margin-bottom: 14pt; }
"""


def render_pdf(doc: dict) -> Tuple[bytes, bytes, int]:
    """Returns (pdf bytes, first page PNG thumbnail, page count). Pure function of the stored document."""
    import pymupdf

    lang = doc.get("language", "en")
    L = LABELS.get(lang, LABELS["en"])
    s = doc["snapshot"]
    sender = s["sender_lines"]
    body_html = (
        f"<div class='sender'>{'<br/>'.join(('<b>' + html.escape(x) + '</b>') if i == 0 else html.escape(x) for i, x in enumerate(sender))}</div>"
        f"<div class='date'>{html.escape(s['date_text'])}</div>"
        f"<div class='to'>{'<br/>'.join(html.escape(x) for x in s['recipient_lines'])}</div>"
        + (f"<div class='subject'>{html.escape(L['subject'])}: {html.escape(doc['subject'])}</div>" if doc.get("subject") else "")
        + _p(doc["body"])
    )
    W, H = pymupdf.paper_size("a4")
    margin, top, bottom = 56, 60, 70
    where = pymupdf.Rect(margin, top, W - margin, H - bottom)
    story = pymupdf.Story(html=f"<body>{body_html}</body>", user_css=CSS, archive=pymupdf.Archive(str(ASSETS)))
    writer_out = io.BytesIO()
    writer = pymupdf.DocumentWriter(writer_out)
    more, page_no = 1, 0
    while more:
        dev = writer.begin_page(pymupdf.Rect(0, 0, W, H))
        more, _ = story.place(where)
        story.draw(dev)
        writer.end_page()
        page_no += 1
        if page_no > 12:
            break
    writer.close()
    pdf = pymupdf.open("pdf", writer_out.getvalue())
    stamp = ASSETS / f"stamp-{lang if lang in LANGS else 'en'}.png"
    font = str(ASSETS / "DejaVuSans.ttf")
    n = pdf.page_count
    for i, page in enumerate(pdf):
        page.insert_font(fontname="dv", fontfile=font)
        if i == 0:
            page.insert_image(pymupdf.Rect(W - margin - 92, top - 18, W - margin, top + 74), filename=str(stamp))
        page.draw_line((margin, H - 50), (W - margin, H - 50), color=(1, 0.42, 0), width=0.8)
        page.insert_textbox(pymupdf.Rect(margin, H - 46, W - margin - 60, H - 18), L["footer"], fontname="dv",
                            fontsize=7.5, color=(0.35, 0.39, 0.45))
        page.insert_textbox(pymupdf.Rect(W - margin - 60, H - 46, W - margin, H - 18), f"{L['page']} {i + 1}/{n}",
                            fontname="dv", fontsize=7.5, color=(0.35, 0.39, 0.45), align=2)
    pdf.set_metadata({"title": doc.get("title") or L["default_title"], "author": (sender[0] if sender else ""),
                      "creator": "ask Elon", "producer": "ask Elon", "subject": doc.get("subject") or ""})
    pdf.subset_fonts()
    data = pdf.tobytes(garbage=3, deflate=True)
    page = pdf[0]
    pix = page.get_pixmap(matrix=pymupdf.Matrix(480 / page.rect.width, 480 / page.rect.width))
    thumb = pix.tobytes("png")
    return data, thumb, n


def filename_for(doc: dict) -> str:
    base = unicodedata.normalize("NFKD", (doc.get("title") or "pismo").replace("ł", "l").replace("Ł", "L"))
    base = re.sub(r"[^A-Za-z0-9]+", "-", "".join(c for c in base if not unicodedata.combining(c))).strip("-").lower()[:60] or "pismo"
    d = doc.get("created_at")
    return f"ask-elon-{base}-{d.strftime('%Y-%m-%d') if hasattr(d, 'strftime') else 'dokument'}.pdf"


# ---------------- signed links ----------------
def sign(secret: str, doc_id: str, kind: str, owner: str, exp: int) -> str:
    return hmac.new(secret.encode(), f"{doc_id}:{kind}:{owner}:{exp}".encode(), hashlib.sha256).hexdigest()[:32]


def signed_path(secret: str, d: dict, kind: str, ttl: int = LINK_TTL) -> str:
    exp = int(time.time()) + ttl
    v = int(d["updated_at"].timestamp()) if hasattr(d.get("updated_at"), "timestamp") else 0
    return f"/chat-documents/{d['chat_doc_id']}/{kind}?exp={exp}&v={v}&sig={sign(secret, d['chat_doc_id'], kind, d['user_id'], exp)}"


def public(d: dict, secret: str, full: bool = False) -> dict:
    out = {k: v for k, v in d.items() if k not in PUBLIC_EXCLUDE and (full or k not in ("body", "translation", "snapshot"))}
    out["has_translation"] = bool(d.get("translation"))
    out["filename"] = filename_for(d)
    out["thumb_url"] = signed_path(secret, d, "thumb")
    out["pdf_url"] = signed_path(secret, d, "pdf")
    return out


def card(d: dict) -> dict:
    """Minimal metadata kept inside the chat message (history shows the card without an extra request)."""
    return {k: d.get(k) for k in ("chat_doc_id", "type", "title", "language", "created_at")}


class DocPatch(BaseModel):
    subject: Optional[str] = None
    recipient: Optional[str] = None
    body: Optional[str] = None


async def ensure_indexes(db):
    await db.chat_documents.create_index("chat_doc_id", unique=True)
    await db.chat_documents.create_index([("user_id", 1), ("created_at", -1)])


class Service:
    def __init__(self, db, secret: str, new_id: Callable[[str], str], now: Callable, prefix: str = "union-elon"):
        self.db, self.secret, self.new_id, self.now, self.prefix = db, secret, new_id, now, prefix

    async def create(self, user: dict, spec: dict, thread_id: str, message_id: str) -> Optional[dict]:
        """Renders + stores a document from a parsed block. Returns the stored doc or None (daily limit).
        Raises storage_quota.StorageFull when the user's storage is full (nothing is stored then)."""
        uid = user["user_id"]
        t = self.now()
        day_ago = t.timestamp() - 86400
        recent = await self.db.chat_documents.count_documents({"user_id": uid, "created_ts": {"$gte": day_ago}})
        if recent >= MAX_PER_DAY:
            logger.warning("chat document daily limit reached for %s", uid)
            return None
        case_id = None
        if thread_id and thread_id != "main":
            c = await self.db.cases.find_one({"case_id": thread_id, "user_id": uid}, {"_id": 0, "case_id": 1})
            case_id = c["case_id"] if c else None
        loc = user.get("locale") if user.get("locale") in LANGS else "pl"
        title = spec["title"] or TYPE_TITLES[loc][spec["type"]]
        doc = {"chat_doc_id": self.new_id("cdoc"), "user_id": uid, "thread_id": thread_id, "case_id": case_id,
               "message_id": message_id, **spec, "title": title,
               "translation_lang": loc if spec.get("translation") else None,
               "snapshot": build_snapshot(user, spec, t), "created_at": t, "updated_at": t, "created_ts": t.timestamp(),
               "deleted": False}
        await self._render_store(doc, user)
        await self.db.chat_documents.insert_one(dict(doc))
        return doc

    async def _render_store(self, doc: dict, user: dict, replacing: int = 0):
        pdf, thumb, pages = await run_in_threadpool(render_pdf, doc)
        await storage_quota.ensure_room(self.db, user, len(pdf), replacing=replacing)
        base = f"{self.prefix}/chat-docs/{doc['user_id']}/{uuid.uuid4().hex}"
        await run_in_threadpool(storage.put_object, f"{base}.pdf", pdf, "application/pdf")
        await run_in_threadpool(storage.put_object, f"{base}_thumb.png", thumb, "image/png")
        doc.update(pdf_path=f"{base}.pdf", thumb_path=f"{base}_thumb.png", size=len(pdf), pages=pages)

    async def enrich_messages(self, uid: str, msgs: List[dict]) -> List[dict]:
        """Adds fresh signed thumbnail links to document cards in chat history; drops deleted documents."""
        ids = [c["chat_doc_id"] for m in msgs for c in (m.get("documents") or [])]
        if not ids:
            return msgs
        found = {d["chat_doc_id"]: d for d in await self.db.chat_documents.find(
            {"user_id": uid, "chat_doc_id": {"$in": ids}, "deleted": {"$ne": True}}, {"_id": 0}).to_list(len(ids))}
        for m in msgs:
            if m.get("documents"):
                m["documents"] = [{**card(found[c["chat_doc_id"]]), "thumb_url": signed_path(self.secret, found[c["chat_doc_id"]], "thumb")}
                                  if c["chat_doc_id"] in found else {**c, "deleted": True} for c in m["documents"]]
        return msgs


def build_router(svc: Service, current_user: Callable[[Request], Awaitable[dict]], rate_limit: Callable) -> APIRouter:
    db, secret = svc.db, svc.secret
    r = APIRouter(prefix="/api/chat-documents", tags=["chat-documents"])

    async def own(doc_id: str, uid: str) -> dict:
        d = await db.chat_documents.find_one({"chat_doc_id": doc_id[:64], "user_id": uid, "deleted": {"$ne": True}}, {"_id": 0})
        if not d:
            raise HTTPException(404, "Document not found")
        return d

    @r.get("")
    async def list_docs(request: Request, limit: int = 20, offset: int = 0):
        user = await current_user(request)
        uid = user["user_id"]
        limit, offset = max(1, min(limit, 50)), max(0, offset)
        q = {"user_id": uid, "deleted": {"$ne": True}}
        total = await db.chat_documents.count_documents(q)
        docs = await db.chat_documents.find(q, {"_id": 0, "body": 0, "translation": 0}).sort("created_at", -1) \
            .skip(offset).limit(limit).to_list(limit)
        case_ids = list({d["case_id"] for d in docs if d.get("case_id")})
        titles = {c["case_id"]: c["title"] for c in await db.cases.find(
            {"user_id": uid, "case_id": {"$in": case_ids}}, {"_id": 0, "case_id": 1, "title": 1}).to_list(len(case_ids) or 1)} if case_ids else {}
        items = [{**public(d, secret), "case_title": titles.get(d.get("case_id"))} for d in docs]
        return {"items": items, "total": total, "offset": offset, "has_more": offset + len(items) < total}

    @r.get("/{doc_id}")
    async def get_doc(doc_id: str, request: Request):
        user = await current_user(request)
        d = await own(doc_id, user["user_id"])
        c = await db.cases.find_one({"case_id": d.get("case_id"), "user_id": user["user_id"]}, {"_id": 0, "title": 1}) if d.get("case_id") else None
        return {**public(d, secret, full=True), "case_title": c["title"] if c else None}

    @r.put("/{doc_id}")
    async def edit_doc(doc_id: str, body: DocPatch, request: Request):
        user = await current_user(request)
        rate_limit(f"cdoc-edit:{user['user_id']}", 30, 600)
        d = await own(doc_id, user["user_id"])
        if body.body is not None:
            b = clean(body.body, BODY_MAX + 1)
            if len(b) > BODY_MAX:
                raise HTTPException(400, f"Letter too long (max {BODY_MAX} characters)")
            if len(b) < BODY_MIN:
                raise HTTPException(400, "Letter is too short")
            d["body"] = b
        if body.subject is not None:
            d["subject"] = clean(body.subject, LINE_MAX, False)
        if body.recipient is not None and clean(body.recipient, LINE_MAX, False):
            d["recipient"] = clean(body.recipient, LINE_MAX, False)
            d["snapshot"]["recipient_lines"][0] = d["recipient"]
        d["updated_at"] = svc.now()
        try:
            await svc._render_store(d, user, replacing=int(d.get("size") or 0))
        except storage_quota.StorageFull:
            raise
        except Exception:
            logger.exception("chat document re-render failed")
            raise HTTPException(500, "Could not create the PDF")
        await db.chat_documents.update_one({"chat_doc_id": d["chat_doc_id"], "user_id": user["user_id"]}, {"$set": {
            k: d[k] for k in ("body", "subject", "recipient", "snapshot", "updated_at", "pdf_path", "thumb_path", "size", "pages")}})
        return {**public(d, secret, full=True)}

    @r.delete("/{doc_id}")
    async def delete_doc(doc_id: str, request: Request):
        user = await current_user(request)
        res = await db.chat_documents.update_one({"chat_doc_id": doc_id[:64], "user_id": user["user_id"], "deleted": {"$ne": True}},
                                                 {"$set": {"deleted": True, "deleted_at": svc.now()}})
        if not res.matched_count:
            raise HTTPException(404, "Document not found")
        return {"ok": True}

    @r.get("/{doc_id}/{kind}")
    async def doc_file(doc_id: str, kind: str, request: Request, exp: int = 0, sig: str = "", dl: int = 0):
        if kind not in ("pdf", "thumb"):
            raise HTTPException(404, "Not found")
        if sig:
            d = await db.chat_documents.find_one({"chat_doc_id": doc_id[:64], "deleted": {"$ne": True}}, {"_id": 0})
            ok = d and exp >= time.time() and hmac.compare_digest(sig, sign(secret, d["chat_doc_id"], kind, d["user_id"], exp))
            if not ok:
                raise HTTPException(404, "Not found")  # expired/forged links look like missing files
        else:
            user = await current_user(request)
            d = await own(doc_id, user["user_id"])
        try:
            data, _ = await run_in_threadpool(storage.get_object, d["pdf_path"] if kind == "pdf" else d["thumb_path"])
        except storage.ObjectNotFound:
            raise HTTPException(404, "File not found in storage")
        headers = {"Cache-Control": "private, max-age=3600", "X-Content-Type-Options": "nosniff"}
        if kind == "pdf":
            name = filename_for(d)
            headers["Content-Disposition"] = f"{'attachment' if dl else 'inline'}; filename=\"{name}\"; filename*=UTF-8''{quote(name)}"
        return Response(content=data, media_type="application/pdf" if kind == "pdf" else "image/png", headers=headers)

    return r
